"""
Build a print-ready PDF (6×9in, 0.125in bleeds) for 'No Blue Sky: Built from Dust'.
Produces HTML for weasyprint with proper print CSS.
"""

import os, re, sys
from xml.sax.saxutils import escape as xmlescape

BOOK_DIR = "/home/bob/books/No_Blue_Sky_Series/Book_I_Built_from_Dust"
MANUSCRIPT = os.path.join(BOOK_DIR, "manuscript.md")
PDF_OUT = os.path.join(BOOK_DIR, "Print", "No_Blue_Sky_1_Built_from_Dust_Print_Ready.pdf")
HTML_OUT = os.path.join(BOOK_DIR, "Print", "No_Blue_Sky_1_Built_from_Dust_Print_Ready.html")

TITLE = "No Blue Sky: Built from Dust"
SUBTITLE = "The First Martian Generation"
AUTHOR = "Bob N."

# Read manuscript
with open(MANUSCRIPT) as f:
    manuscript_text = f.read()

lines = manuscript_text.split("\n")

# Build HTML body
body_parts = []

# Title page
body_parts.append(f"""
<div class="title-page">
  <p class="series">No Blue Sky Series &bull; Book I</p>
  <h1 class="book-title">{xmlescape(TITLE)}</h1>
  <p class="subtitle">{xmlescape(SUBTITLE)}</p>
  <p class="author">{xmlescape(AUTHOR)}</p>
</div>
""")

# Copyright page
body_parts.append(f"""
<div class="copyright-page">
  <p><strong>Copyright &copy; 2026 by {xmlescape(AUTHOR)}</strong></p>
  <p>All rights reserved. No part of this publication may be reproduced, distributed, or transmitted in any form or by any means, including photocopying, recording, or other electronic or mechanical methods, without the prior written permission of the publisher, except in the case of brief quotations embodied in critical reviews and certain other noncommercial uses permitted by copyright law.</p>
  <p>This is a work of fiction. Names, characters, places, and incidents either are the product of the author's imagination or are used fictitiously. Any resemblance to actual persons, living or dead, events, or locales is entirely coincidental.</p>
  <p class="publisher">Self-Published</p>
</div>
""")

# Now process the manuscript content
# We'll convert markdown to HTML, treating headings properly
# Skip the first few title lines

state = "front"
for line in lines:
    stripped = line.strip()

    if state == "front":
        # Skip front matter lines until we hit Part I
        if stripped.startswith("# PART"):
            state = "body"
            part_title = stripped.lstrip("# ").strip()
            body_parts.append(f"<h1>{xmlescape(part_title)}</h1>")
        continue

    # Convert markdown to HTML
    if stripped.startswith("## "):
        heading_text = stripped[3:].strip()
        # Chapter headings
        body_parts.append(f"<h2>{xmlescape(heading_text)}</h2>")
    elif stripped.startswith("# ") and stripped[2:].startswith("PART"):
        part_title = stripped[2:].strip()
        body_parts.append(f"<h1>{xmlescape(part_title)}</h1>")
    elif stripped.startswith("---"):
        body_parts.append("<hr/>")
    elif stripped.startswith(">"):
        body_parts.append(f"<blockquote><p>{xmlescape(stripped[1:].strip())}</p></blockquote>")
    elif stripped.startswith("*") and stripped.endswith("*") and not stripped.startswith("**"):
        # Italic lines (often used for section breaks or epigraphs)
        inner = stripped.strip("*").strip()
        body_parts.append(f"<p class=\"epigraph\">{xmlescape(inner)}</p>")
    elif stripped == "":
        body_parts.append("<br/>")
    else:
        # Regular paragraph - handle inline formatting
        text = stripped
        # Bold
        text = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", text)
        # Italic
        text = re.sub(r"(?<!\*)\*([^*]+)\*(?!\*)", r"<em>\1</em>", text)
        body_parts.append(f"<p>{text}</p>")

# About the author page
body_parts.append(f"""
<div class="about-author">
  <h2>About the Author</h2>
  <p>{xmlescape(AUTHOR)} is a writer of speculative fiction exploring humanity's future beyond Earth. <em>{xmlescape(TITLE)}</em> is the first book in the No Blue Sky series.</p>
</div>
""")

body_html = "\n".join(body_parts)

# Full HTML document with print CSS
# 6×9in + 0.125in bleeds = 6.25in × 9.25in = 450pt × 666pt
css = """
@page {
  size: 6.25in 9.25in;
  margin: 0.75in;
  @bottom-center {
    content: counter(page);
    font-size: 9pt;
    font-family: Georgia, 'Times New Roman', serif;
    color: #888;
  }
}

@page :first {
  @bottom-center { content: none; }
}

body {
  font-family: Georgia, 'Times New Roman', serif;
  line-height: 1.5;
  font-size: 11pt;
  color: #000;
  widows: 2;
  orphans: 2;
}

/* Bleed markers */
.bleed-line {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
}

/* Title page */
.title-page {
  text-align: center;
  padding-top: 30%;
  page-break-after: always;
}
.title-page .series {
  font-size: 11pt;
  color: #666;
  margin-bottom: 2em;
}
.title-page .book-title {
  font-size: 22pt;
  font-weight: bold;
  margin-bottom: 0.3em;
  text-align: center;
  page-break-before: avoid;
}
.title-page .subtitle {
  font-size: 14pt;
  font-style: italic;
  color: #555;
  margin-bottom: 1.5em;
}
.title-page .author {
  font-size: 16pt;
  margin-top: 1em;
}

/* Copyright page */
.copyright-page {
  font-size: 9pt;
  line-height: 1.4;
  padding-top: 15%;
  page-break-after: always;
}
.copyright-page p {
  margin: 0.5em 0;
  text-indent: 0;
}
.copyright-page .publisher {
  text-align: center;
  font-style: italic;
  margin-top: 2em;
}

/* Chapter titles */
h1 {
  text-align: center;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 16pt;
  font-weight: bold;
  page-break-before: always;
  margin: 3em 0 1.5em 0;
}

h2 {
  text-align: center;
  font-family: 'Helvetica Neue', Arial, sans-serif;
  font-size: 14pt;
  font-weight: bold;
  page-break-before: always;
  margin: 3em 0 1.5em 0;
}

/* Body text */
p {
  margin: 0.15em 0;
  text-indent: 1.2em;
  text-align: justify;
  line-height: 1.5;
}

h1 + p, h2 + p, h3 + p {
  text-indent: 0;
}

/* Epigraph style */
p.epigraph {
  text-align: center;
  font-style: italic;
  color: #555;
  text-indent: 0;
  margin: 1em 2em;
}

/* Blockquotes */
blockquote {
  margin: 0.5em 1.5em;
  font-style: italic;
  color: #444;
}
blockquote p {
  text-indent: 0;
  margin: 0.3em 0;
}

/* Horizontal rule */
hr {
  border: none;
  border-top: 0.5pt solid #999;
  margin: 1.5em 25%;
  width: 50%;
}

/* About author */
.about-author {
  page-break-before: always;
  padding-top: 15%;
  font-size: 10pt;
  line-height: 1.5;
}
.about-author h2 {
  text-align: center;
  font-size: 14pt;
  page-break-before: avoid;
}
.about-author p {
  text-indent: 0;
}
"""

full_html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<title>{xmlescape(TITLE)}</title>
<style>{css}</style>
</head>
<body>
{body_html}
</body>
</html>"""

# Write HTML
with open(HTML_OUT, "w", encoding="utf-8") as f:
    f.write(full_html)

print(f"Print HTML written: {HTML_OUT}")
print(f"HTML size: {len(full_html):,} bytes")
